    rho_2 = _vec(p["\\rho_2"])
    e3 = _vec(p["e3"])
    g = p["g"]
    l_1 = _vec(p["l_1"])
    m1 = p["m1"]
    m2 = p["m2"]
    _t0 = np.cross(Omega_R1, J1 @ Omega_R1) * -1
    _t1 = np.cross(Omega_R1, np.cross(rho_1, np.cross(Omega_R1, rho_1))) * (m1 * -1)
