    _t3 = R1.T
    _t4 = np.cross(Omega_R2, rho_2)
    _t5 = _t3 @ (R2 @ _t4)
    _t6 = np.cross(l_1, np.cross(Omega_R1, _t5)) * m2
    _t7 = _t3 @ (R2 @ np.cross(Omega_R2, _t4))
    _t8 = m2 * -1
    _t9 = np.cross(Omega_R1, np.cross(l_1, _t2)) * _t8
