    _t11 = m2 * g
    _t12 = J1 @ Omega_R1 @ Omega_R1 * 0.5 + m1 * _t1 + _t3 + m2 * _t6
    _t13 = _t12 + J2 @ Omega_R2 @ Omega_R2 * 0.5 + m2 * _t8 + m2 * _t9
