    _t15 = _t14 + _t7 @ _t5 * m2 * -1 + _t5 @ _t5 * m2 * -0.5
    _t16 = _t15 + m1 * g * (R1 @ rho_1 @ e3) + _t11 * (R1 @ l_1 @ e3)
    return _t16 + _t11 * (R2 @ rho_2 @ e3)
